#!/usr/bin/env python3
"""Build concise research-only reports from the validated 003 data and test outputs."""
from pathlib import Path
import csv,json,collections,datetime
ROOT=Path(__file__).resolve().parents[1]; DATA=ROOT/'dataset/v1'; REPORTS=ROOT/'reports'; FIX=ROOT/'fixtures'
def jl(name): return [json.loads(x) for x in (DATA/(name+'.jsonl')).read_text().splitlines() if x.strip()]
def load(path): return json.loads(path.read_text(encoding='utf-8'))
def write(name,text): (REPORTS/name).write_text(text.rstrip()+'\n',encoding='utf-8')
REPORTS.mkdir(exist_ok=True)
dataset=load(REPORTS/'dataset-validation.json');fixture=load(REPORTS/'fixture-validation.json');tests=load(REPORTS/'regression-tests.json')
version=load(REPORTS/'version-map.json');review=[]
with (REPORTS/'source-claim-review.csv').open(encoding='utf-8',newline='') as f: review=list(csv.DictReader(f))
disps=collections.Counter(x['disposition'] for x in review)
parts=['software_types','engineering_practices','sdlc_stages','architecture_patterns','prompt_patterns','roadmap_patterns','verification_gates','reference_projects','sources','relationships']
counts={p:len(jl(p)) for p in parts}; types={r['id']:r for r in jl('software_types')}
calibrated={'software_type.ai_agents':'ai_agent','software_type.apis':'authenticated_api','software_type.cli_tools':'offline_cli'}
not_calibrated=sorted(set(types)-set(calibrated))
branch_info={x['directory']:x for x in fixture.get('results',[])}
# Graph/coverage report.
lines=['# Graph coverage and calibration boundary','',f"Dataset version **{dataset['dataset_version']}**; schema version **{dataset['schema_version']}**. This report describes graph navigability and fixture scope, not general product coverage.",'', '## Fixture branches','', '| Fixture | Software type | Selected records | Rejected records | Rejected requirements | Exact source traces | Gate outcomes |','|---|---|---:|---:|---:|---:|---|']
for directory in ['ai_agent','authenticated_api','offline_cli']:
 b=load(FIX/directory/'brief.json'); s=load(FIX/directory/'expected_selection.json'); r=load(FIX/directory/'expected_rejections.json'); t=load(FIX/directory/'evidence_trace.json')
 lines.append(f"| `{directory}` | `{', '.join(b['software_type_ids'])}` | {len(s['selected_records'])} | {len(r['rejected_records'])} | {len(r['rejected_requirements'])} | {len(t['traces'])} | {', '.join(f'{k}: {v}' for k,v in s['gate_outcomes'].items())} |")
lines += ['', 'The checker validates each selected record against its declared software-type applicability, an active typed category-to-record edge, a `supported_by` edge to the source record, and that source record’s exact claim locator. All selected records in these three narrow scenarios have at least one trace; the trace files enumerate the selected records’ linked sources. Rejected requirements and rejected records remain separately identified. The negative-control branch is not a fourth product category.', '', '## Dataset and graph totals','', '| Partition | Records |','|---|---:|']
for p in parts: lines.append(f'| `{p}` | {counts[p]} |')
active=dataset['counts']['active_relationship_count'];sup=dataset['counts']['superseded_relationship_count']
lines += ['', f"Relationships: **{counts['relationships']} total; {active} active; {sup} superseded historical edges**. All active edge endpoints and source IDs resolve. Applicability arrays mirror typed category edges but are not treated as research-coverage evidence. Three broad repository-example edges remain as explicit superseded history.", '', '## Calibration boundary','', 'A fixture proves only the scenario it exercises, not all products in the same category. The AI-agent, API, and CLI rows below have one worked scenario each; they are not general category certification.', '', '| Software type | 003 status | Evidence boundary |','|---|---|---|']
for tid in sorted(types):
 if tid in calibrated:
  directory=calibrated[tid]; brief=load(FIX/directory/'brief.json')
  lines.append(f"| `{tid}` | `FIXTURE_DEMONSTRATED_NARROW_SCENARIO` | {brief['description']} |")
 else:
  lines.append(f'| `{tid}` | `NOT_CALIBRATED` | No dedicated 003 acceptance fixture or category-specific claim calibration; do not infer support from applicability arrays. |')
lines += ['', '### Explicitly sparse/un-calibrated categories','', 'The required sparse categories—`web_applications`, `mobile_applications`, `developer_tools`, and `data_pipelines`—remain `NOT_CALIBRATED`. SaaS, security products, and libraries also remain `NOT_CALIBRATED` because no dedicated fixture was built in this research-only increment.', '', '### Graph policy','', 'Active relationship predicates distinguish `applies_to` (category to knowledge record), `exemplified_by` (category/reference example mapping), and `supported_by` (knowledge record to source). Reference-project applicability was narrowed to the verified primary category; the three displaced inherited edges were retained with a supersession status and are excluded from active traversal. A category/source/edge link is not proof that a recommendation applies or that a practice was executed.']
write('graph-coverage.md','\n'.join(lines))
# Coverage gaps.
gap=['# Coverage gaps','', 'This is a deliberately bounded research checkpoint, not a market-readiness assessment.', '', '## Not calibrated in 003','']
for tid in not_calibrated: gap.append(f"- `{tid}` — **NOT_CALIBRATED**. The type’s overview record and general cross-cutting records may exist, but no dedicated golden fixture validates category-specific selection, exclusion, evidence locators, or gate behavior.")
gap += ['', '## Narrowly demonstrated only','', '- `software_type.ai_agents`: one external/untrusted-content agent with read and bounded-write tools, side effects, no standing high-impact approval, and missing candidate/run/recovery evidence.', '- `software_type.apis`: one authenticated, role-authorized, persisted-record, single-service API; tenanting, queueing, gateway, billing, microservices, and Kubernetes are not presumed.', '- `software_type.cli_tools`: one offline local-file processor, no account/network/shared-state boundary, and no authorized destructive writes; packaging and local recovery are conditional.', '', 'These examples do not establish complete category coverage. Before any broader claim, add category-specific evidence and a separate worked fixture. No additional category content was expanded merely to improve counts.']
write('coverage-gaps.md','\n'.join(gap))
# Negative controls.
neg=next((x for x in fixture['results'] if x['directory']=='conflict_missing_evidence'),None)
failed=['# Failed-negative-controls.md — adversarial abstention checks','', '“Failed” here names the controls that would fail unsafe/unsupported claims; all five controls behaved as designed in the verifier. No test, CI, standard-conformance, or release outcome is claimed.','', '| Control | Expected status | Derived status | Result | Rationale |','|---|---|---|---|---|']
if neg:
 for c in neg['negative_cases']: failed.append(f"| `{c['case_id']}` | `{c['expected_status']}` | `{c['derived_status']}` | {'PASS' if c['expected_status']==c['derived_status'] else 'FAIL'} | {c['reason']} |")
failed += ['', '## Interpretation','', '- Mobile-stack documentation is not selected as evidence for the API record: `INAPPLICABLE`.', '- The official IEEE catalog identifies ISO/IEC/IEEE 12207:2026 as active and superseding 2017, but organizational adoption and normative applicability remain unreviewed: `INCOMPLETE`; no compliance assertion is allowed.', '- Pinned test source and workflow configuration describe authored/configured content only. With no candidate identity or execution artifact, the test gate remains `INCOMPLETE`.', '- AWS workload-segmentation and Twelve-Factor process guidance stay within their respective scopes; architecture selection remains `CONDITIONAL`, not a universal winner.', '- Unknown requirement IDs with no catalog match cause explicit `INCOMPLETE` abstention; they are not silently mapped.', '', 'Regression tests intentionally mutate each negative case and assert that the control then reports an error.']
write('failed-negative-controls.md','\n'.join(failed))
# Source calibration report.
source_lines=['# Focused source-to-claim review','', f"**{len(review)}** high-impact mappings were independently spot-checked from the three fixture branches. Dispositions: **{disps.get('CONFIRMED',0)} CONFIRMED**, **{disps.get('SYNTHESIS',0)} SYNTHESIS**, **{disps.get('UNRESOLVED',0)} UNRESOLVED**, **{disps.get('CONTRADICTED',0)} CONTRADICTED**. The review set is fixture-critical; it is not an indiscriminate audit of all 62 inherited sources.",'', '| Source ID | Disposition | Evidence class | Scope note |','|---|---|---|---|']
for x in review:
 note=x.get('overbreadth_or_conflict','').replace('|','\\|').replace('\n',' ')
 if len(note)>350: note=note[:347].rsplit(' ',1)[0]+'…'
 source_lines.append(f"| `{x['source_id']}` | {x['disposition']} | `{x['evidence_classification']}` | {note} |")
source_lines += ['', '## Standards and normativity','', '- IEEE’s official catalog listing was checked for ISO/IEC/IEEE 12207:2026: active status, publication/approval metadata, and supersession of 2017 are stated in the source record. The full normative text was not inspected, and organizational adoption is unknown; therefore no automatic conformity or mandatory gate claim is permitted.', '- NIST SP 800-218 (SSDF 1.1) is used as **recommended, adaptable, informative guidance**. Its source claim is explicitly a synthesis; it does not establish universal gates, ordering, or completion.', '- NIST SP 800-53 is not referenced by the three fixture selections or source-claim review set, so no edition/normativity claim about it is made here.', '', '## Evidence limits','', 'Pinned repository files and tree inventories establish file/path presence or authored test/workflow content at a commit, not execution or compliance. The fixtures retain `not_run` status for tests, CI, and releases. Source locators are exact source-record claim locators; source limitations and evidence classes remain visible.']
write('source-claim-review.md','\n'.join(source_lines))
# Change log.
ch=['# Change log — STUDIO-KNOWLEDGE-003','', '## 2026-10-31 — research-only calibration','', '- Preserved every stable record ID found in the immutable 001 and 002 checkpoint indexes; added record-version changes instead of replacing IDs. The original archive digests are recorded in `research/immutable-input-digests.json`; prior ZIPs are intentionally not included.', '- Added strict Draft 2020-12 typed contracts for lifecycle stages, prompt patterns, tri-state verification gates, roadmap tasks/dependencies, architecture options/tradeoffs, and repository reference metadata. Schema/data versions are 1.1.0/1.2.0.', '- Reworked six architecture patterns to use explicit option IDs, applicability conditions, benefits, costs, risks, exclusions, evidence classes, and separate failure-mode lists. No architecture is declared a universal default.', '- Scoped agent-instruction findings to FastAPI, ripgrep, and OpenAI Agents SDK separately; pinned reference files to commit plus path and kept test/CI/release execution status `not_run`.', '- Updated source metadata/claims for AWS workload guidance, Twelve-Factor process guidance, the CLI guide, the OpenAI Agents SDK trace test, selected commit-pinned files, and the IEEE 12207 catalog entry. Added three pinned tree-inventory sources. Full normative text was not inspected.', '- Retained three stable inherited relationship IDs as `superseded` history when repository applicability was narrowed. Active graph is validated separately from superseded history.', '- Added three deterministic acceptance fixtures and one dedicated abstention/control branch, with exact source locators and typed graph paths. Added a golden-ID index to detect silent selection/rejection changes.', '- Added five machine-checkable negative controls: stack mismatch, superseded standard, absent test execution, source-scope tension, and unknown requirement abstention.', '- Added a safe migration completion marker and pristine-baseline guard; completed migration reruns do not write dataset files. Regression test confirms versioned user enrichment survives a rerun.', '- Added schema/graph/roadmap/fixture/manifest/idempotency and preservation regressions. No Studio, product code, hosted service, generator, ingestion path, vector search, frontend, API, or payment system was implemented or modified.', '', '## Known limits','', '- The fixture checker verifies curated expected selections; it is not a general brief-to-selection generator.', '- Seven software types remain `NOT_CALIBRATED`; even the three represented types have only one narrow worked scenario each.', '- No tests, CI, releases, deployments, or standard-conformance assessments were executed.']
write('change-log.md','\n'.join(ch))
# Machine-readable validation report.
version=load(REPORTS/'version-map.json')
source_review={'mapping_count':len(review),'dispositions':dict(disps),'failures':len(load(ROOT/'research/source-review-results.json').get('failures',[]))}
validation={'project':'STUDIO-KNOWLEDGE-003','scope':'research-only fixture/data QA; no Studio integration','dataset_version':dataset['dataset_version'],'schema_version':dataset['schema_version'],'status':'PASS' if dataset['status']=='PASS' and fixture['status']=='PASS' and tests['status']=='PASS' else 'FAIL','dataset_validation':{'status':dataset['status'],'error_count':dataset['error_count'],'counts':dataset['counts']},'fixture_validation':{'status':fixture['status'],'error_count':fixture['error_count'],'fixture_count':fixture['fixture_count'],'category_coverage':fixture['fixture_category_coverage'],'branches':fixture['results']},'regression_tests':{'status':tests['status'],'tests_run':tests['tests_run'],'failures':len(tests['failures']),'errors':len(tests['errors'])},'checkpoint_preservation':version['preservation'],'source_claim_review':source_review,'package_hygiene':{'original_zip_files_embedded':False,'required_verifier':'scripts/verify_fixtures.py','manifest':'manifest.json and detached manifest.sha256; final archive checksum is a detached sidecar','package_excludes':['__pycache__','*.pyc','*.tmp','original 001/002 ZIPs']},'execution_claims':{'tests_executed_for_products':False,'ci_executed':False,'release_executed':False,'verification_gates_return_pass':False},'acceptance_boundary':'PASS indicates research dataset integrity and the narrow acceptance fixture contracts only; it is not production or category-wide readiness.'}
(REPORTS/'validation-report.json').write_text(json.dumps(validation,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
# Decision.
dec=['# STUDIO-KNOWLEDGE-003 decision','', '## Separate gate decisions','', '| Area | Decision | Basis |','|---|---|---|', '| Dataset integrity | **GO** | Base/category schemas, IDs, source links, active graph, repository pins and roadmap DAG validate; all 001/002 stable IDs are preserved; final package hashes will be independently verified. |','| Fixture selection reliability | **GO — narrow fixtures only** | Three curated briefs replay against golden selected/rejected IDs, applicability, satisfied/false branch conditions, exact typed source paths/locators, missing-input records and incomplete gates; five negative controls abstain or narrow scope as expected. The checker validates the fixture contract, not arbitrary user briefs. |','| Studio integration | **NO-GO / NOT STARTED** | Explicitly out of scope. No generator, ingestion service, vector search, API, frontend, payment system or production integration was implemented. |','', '## Overall disposition: PARTIAL','', '003 passes its research-only data-integrity and narrow fixture acceptance gates, but it is not production readiness or market readiness. Product integration remains a separate future authorization and must not be inferred from fixture validation. Seven software types remain `NOT_CALIBRATED`; the three represented types have one scenario each. No product tests, CI, release, deployment, or compliance result exists.', '', '## Do not proceed to Stage 004 yet','', 'The directive says not to start Stage 004 unless deterministic, traceable, correctly abstaining selection is established. The curated paper fixtures satisfy that narrow prerequisite, but the independent review does **not** authorize Stage 004 work. Any next stage requires an explicit new instruction and must first define a general selection algorithm, broader scenario coverage, and operational safety boundaries.']
write('decision.md','\n'.join(dec))
# README.
readme=['# STUDIO-KNOWLEDGE-003 — research-only calibration','', 'This checkpoint converts 002’s paper examples into data-only, replayable acceptance fixtures. It adds typed schemas, graph/provenance validation, three narrow software briefs, a separate negative-control branch, and a regression suite. It does **not** implement a product generator or modify Studio.', '', '## Contents','', '- `dataset/v1/` — versioned knowledge, source, and typed relationship JSONL.', '- `schemas/` — Draft 2020-12 contracts, including category-specific shapes.', '- `fixtures/ai_agent/`, `fixtures/authenticated_api/`, `fixtures/offline_cli/` — the three acceptance fixtures. `fixtures/conflict_missing_evidence/` holds machine-readable abstention controls.', '- `fixtures/golden-id-map.json` — exact selected/rejected ID oracle.', '- `scripts/verify_fixtures.py` — read-only fixture checker entry point (writes only its JSON report, never the dataset).', '- `scripts/validate_dataset.py` — schema, graph, source, applicability and roadmap-DAG validation.', '- `tests/` — preservation, mutation, source-import/migration idempotency, negative-control and manifest tests.', '- `reports/graph-coverage.md`, `reports/source-claim-review.csv`, `reports/failed-negative-controls.md`, `reports/decision.md` and `reports/validation-report.json` — scope and acceptance results.', '- `research/record-index-001.json`, `research/record-index-002.json`, and `research/immutable-input-digests.json` — compact stable-ID/hash evidence; original ZIPs are not embedded.', '', '## Reproduce validation','', 'Requires Python 3.10+ and `jsonschema` with Draft 2020-12 support.', '', '```bash\npython3 scripts/validate_dataset.py --report /tmp/dataset-validation.json\npython3 scripts/verify_fixtures.py --report /tmp/fixture-validation.json\npython3 scripts/run_regression_tests.py\npython3 scripts/verify_manifest.py --root .\n```', '', 'The final downloadable ZIP has its own detached `.sha256` sidecar. To verify the archive as well as in-tree files, pass `--archive /path/to/STUDIO_KNOWLEDGE_003_checkpoint.zip`.', '', '## Interpretation','', 'A PASS here means schema/data integrity and the **three curated scenario contracts** validate. It does not mean an arbitrary brief can be selected automatically, every category is researched, tests/CI ran, any release occurred, or a standard is satisfied. API role-denial tests, AI trust/approval/recovery checks, and CLI filesystem tests are future evidence requirements; all relevant gates remain `INCOMPLETE` without candidate-bound results. Seven software types are explicitly `NOT_CALIBRATED`. See `reports/decision.md` for separate GO/PARTIAL/NO-GO decisions.']
(ROOT/'README.md').write_text('\n'.join(readme)+'\n',encoding='utf-8')
print(json.dumps({'reports':['graph-coverage.md','coverage-gaps.md','failed-negative-controls.md','source-claim-review.md','change-log.md','validation-report.json','decision.md'],'status':validation['status'],'source_review':source_review},indent=2))
